   "tipo": "comercial",
   "genero": "noticia",
   "imagen": "https://gestion.pe/resizer/v2/UNCAN25XNREZZPPPD46CYSD6NE.jpg?auth=5fec4787b0e60bbdcc1aa7975d2754eed77b567df5ab330e672ecb0b6141406d&smart=true&width=1200&height=800",
