   "sintesis": "El papa cerró su emotiva jornada en Chiclayo exhortando a docentes y alumnos a resistir la “sumisión al paradigma tecnocrático” y ejercer una ciencia con conciencia social Discurso del Papa León XIV ante los jóvenes universitarios de la USAT de Chiclayo que emocionó a todos 13 Nov, 2026 06:45 p. m.",
